using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;using F=System.Windows.Forms;
namespace GearLab {
 static class MicroTests {
  static int checks;static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
  static void Manifest(Result r,string path){File.WriteAllText(path,new JavaScriptSerializer().Serialize(new {bounds=r.Model.Bounds(),parts=r.Model.Parts.Select(p=>new{id=p.Id,role=p.Role,volume=p.Volume(),reference=p.Reference}).ToArray()}),Encoding.UTF8);}
  static void Images(Result r,string folder,string name){using(var scene=new WpfScene()){scene.Root.Measure(new System.Windows.Size(1000,800));scene.Root.Arrange(new System.Windows.Rect(0,0,1000,800));scene.SetResult(r,false);scene.SavePng(Path.Combine(folder,name+"-assembly.png"),1000,800);foreach(var n in scene.Nodes)if(n.Part.Reference)scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();scene.ConfigureSection(1,.37,true);scene.Fit();scene.SavePng(Path.Combine(folder,name+"-cut.png"),1000,800);scene.ConfigureSection(-1,0,false);foreach(var n in scene.Nodes)if(n.Part.Role!="gear"&&n.Part.Role!="housing")scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();scene.UpdatePose(1.3);scene.Fit();scene.SavePng(Path.Combine(folder,name+"-mechanism.png"),1000,800);scene.Hidden.Clear();scene.RefreshVisibility();scene.SetExploded(true);scene.SavePng(Path.Combine(folder,name+"-exploded.png"),1000,800);}}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   foreach(bool integral in new[]{true,false}){var p=MicroPreset.Starter();p.IntegratedRing=integral;var r=Engine.Calculate(p);Check(r.Valid,"micro geometry: "+string.Join(";",r.Errors));r.Model=CadBuilder.Build(r);Check(r.Model.Valid,"micro CAD: "+string.Join(";",r.Model.Errors));Check(r.Pins==20&&r.Lobes==19&&r.Actual==20&&p.Discs==2&&p.RingOutput,"micro kinematics");Check(Math.Abs(MicroPreset.BodyHeight(p)-26)<1e-6,"nominal 26 mm package");Check(r.Width==42&&r.Height==42,"nominal 42 mm base");Check(r.Model.Parts.Count(q=>q.Role=="bearing")==6,"six bearings");Check(r.Model.Parts.Count(q=>q.Id.Contains("RING_ROLLER"))==(integral?0:20),"integrated/roller mode");foreach(var part in r.Model.Parts){var mesh=PrintExport.Mesh(part);Check(Math.Abs(mesh.SignedVolume()/part.Volume()-1)<.015,"mesh/solid volume "+part.Id);}
    string name=integral?"micro-20":"micro-20-rollers";StepExport.Write(r.Model,Path.Combine(folder,name+"-full.step"));var printed=PrintExport.Select(r.Model,null);Check(printed.Parts.Count==5,"five printed parts");StepExport.Write(printed,Path.Combine(folder,name+"-print.step"));PrintExport.Zip(printed,Path.Combine(folder,name+".zip"));FullDrawingExport.Csv(r.Model,Path.Combine(folder,name+"-full.csv"));FullDrawingExport.Write(printed,"svg",Path.Combine(folder,name+"-print.svg"));FullDrawingExport.Write(printed,"dxf",Path.Combine(folder,name+"-print.dxf"));Manifest(r,Path.Combine(folder,name+".manifest.json"));ReleaseSupport.WriteText(Path.Combine(folder,name+".gear.json"),ReleaseSupport.Serialize(p),Encoding.UTF8);Images(r,folder,name);log.AppendLine("PASS "+name+": 42×42×26 nominal; "+r.Model.Parts.Count+" full bodies; 5 printable parts; STEP/STL/CSV/SVG/DXF; mesh volumes; animation/cut/exploded images.");}
   foreach(int ratio in new[]{8,9,20,30}){var p=MicroPreset.Starter();p.Ratio=ratio;if(Engine.FitOverall(p)){var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Model.Valid,"micro ratio "+ratio+": "+string.Join(";",r.Model.Errors));Check(IntegratedRing.ClearsBridges(r,360),"micro bridge clearance "+ratio);}else log.AppendLine("Unavailable within 42 mm: ratio "+ratio);}
   var invalid=MicroPreset.Starter();invalid.MicroJournal=4;Check(!CadBuilder.Build(Engine.Calculate(invalid)).Valid,"undersized journal blocked");invalid=MicroPreset.Starter();invalid.MicroAdapterHeight=0;Check(!CadBuilder.Build(Engine.Calculate(invalid)).Valid,"motor/shaft/pilot interference blocked");invalid=MicroPreset.Starter();invalid.MicroRollerLength=3;Check(!CadBuilder.Build(Engine.Calculate(invalid)).Valid,"short pin sleeve blocked");
   var old=ReleaseSupport.Parse("{\"Kind\":0}");Check(old.CycloidLayout==0,"legacy layout");var saved=ReleaseSupport.Parse(ReleaseSupport.Serialize(MicroPreset.Starter()));Check(saved.CycloidLayout==1&&saved.MicroJournal==7&&saved.MotorPreset==5,"new project persists");
   using(var form=new MainForm(new TestDialogs()))form.MicroUiRegression(log);
   log.AppendLine("PASS "+checks+" Micro assertions. Internal geometry is independently assigned; ratings of the commercial reference are not validated or transferred.");File.WriteAllText(Path.Combine(folder,"micro-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"micro-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
 }
 public partial class MainForm {
  internal void MicroUiRegression(StringBuilder log){Opacity=0;ShowInTaskbar=false;Show();animation.Stop();Apply(Engine.Starter(0),true);cycleLayout.SelectedIndex=1;if(p.CycloidLayout!=1||!result.Model.Valid||preset.SelectedIndex!=5)throw new Exception("micro layout choice");if(scheme.Enabled||dual.Enabled||!VisibleField("MicroJournal"))throw new Exception("micro mode controls");ShowFullModel();VisibilityTests.Ready(canvas.Viewer.Scene);run.PerformClick();if(!canvas.ShowMotion)throw new Exception("micro 3D start");run.PerformClick();hideHousing.Checked=true;hideHousing.Checked=false;if(canvas.Viewer.Scene.Nodes.Any(n=>n.Surface.Geometry==null))throw new Exception("micro hide/show");cycleLayout.SelectedIndex=0;if(p.CycloidLayout!=0||!result.Model.Valid)throw new Exception("restore ordinary layout");cycleLayout.SelectedIndex=1;if(p.CycloidLayout!=1||p.Overall!=42)throw new Exception("restore micro layout");kind.SelectedIndex=3;if(p.Kind!=3||p.MotorPreset==5||!result.Model.Valid)throw new Exception("leave micro for planetary");preset.SelectedIndex=5;if(p.Kind!=0||p.CycloidLayout!=1||!result.Model.Valid)throw new Exception("micro preset from another type");closingApproved=true;Close();log.AppendLine("PASS UI: Micro/ordinary layout, preset from other kinds, mode-specific controls, 3D run/pause, hiding, returning to planetary.");}
 }
}
